import React, { createContext, useState, useContext, useEffect } from 'react';

// Traductions
const translations = {
  mg: {
    home: 'Fandraisana',
    check: 'Hamarinina',
    learn: 'Fianarana',
    about: 'Momba',
    login: 'Hiditra',
    register: 'Hisoratra',
    logout: 'Hivoaka',
    profile: 'Profil',
    language: 'Fiteny',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',
    welcome: 'Tonga soa',
    getStarted: 'Atombohy',
  },
  fr: {
    home: 'Accueil',
    check: 'Vérifier',
    learn: 'Apprendre',
    about: 'À propos',
    login: 'Connexion',
    register: 'Inscription',
    logout: 'Déconnexion',
    profile: 'Profil',
    language: 'Langue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',
    welcome: 'Bienvenue',
    getStarted: 'Commencer',
  },
  en: {
    home: 'Home',
    check: 'Check',
    learn: 'Learn',
    about: 'About',
    login: 'Login',
    register: 'Register',
    logout: 'Logout',
    profile: 'Profile',
    language: 'Language',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',
    welcome: 'Welcome',
    getStarted: 'Get Started',
  }

};

// Créer le contexte
export const LanguageContext = createContext();

// Provider du contexte
export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState('mg');

  useEffect(() => {
    const savedLanguage = localStorage.getItem('language');
    if (savedLanguage && translations[savedLanguage]) {
      setLanguage(savedLanguage);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('language', language);
  }, [language]);

  const t = (key, defaultValue = key) => {
    return translations[language]?.[key] || defaultValue;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

// Hook personnalisé
export const useTranslation = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useTranslation must be used within a LanguageProvider');
  }
  return context;
};
